#!/bin/bash
# public-api.sh — render AIKit's and AIKitMLX's public symbol graph as text.
#
# W27 of spec ai-layer-aikit-core-2026-10-31, BR-AIL-21 item 5. ONE code path,
# used by two callers (BR-EC-02):
#
#   * a human regenerating the allowlist:  scripts/public-api.sh --write
#   * `PublicSurfaceTests`, which runs this and diffs the result against
#     AIKitPublicAPI.txt
#
# The test runs THIS script rather than its own copy of the rendering, so the
# allowlist cannot be generated by one rule and checked by another.
#
# Needs: swift. Nothing else.
#
# The JSON -> text rendering is `Sources/public-api-render`, an executable
# target of this package — it was a Python script until the operator asked on
# PR #18 what Python was doing rendering a Swift package's own surface. A shell
# cannot read the symbol graph honestly, but Swift can, and the machine running
# this gate has a Swift toolchain by construction because it is building AIKit.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

WRITE=0
[[ "${1:-}" == "--write" ]] && WRITE=1

# A scratch path of our own. NOT the package's `.build`: this runs from inside
# `swift test`, and two SwiftPM builds sharing one scratch path contend for its
# lock. It is kept between runs on purpose — a warm incremental run is ~3s
# against ~40s cold.
SCRATCH="$ROOT/.build/public-api"
GRAPHS="$SCRATCH/symbolgraph"

emit_graphs() {
    for target in AIKit AIKitMLX; do
        swift build \
            --scratch-path "$SCRATCH" \
            --target "$target" \
            -Xswiftc -emit-symbol-graph \
            -Xswiftc -emit-symbol-graph-dir -Xswiftc "$GRAPHS" \
            -Xswiftc -symbol-graph-minimum-access-level -Xswiftc public \
            >&2
    done
}

mkdir -p "$GRAPHS"
emit_graphs
# A build with nothing to do emits no graph, so a missing file means the graphs
# were deleted under an up-to-date build. Wipe and redo rather than render a
# stale or absent surface as success.
if [[ ! -f "$GRAPHS/AIKit.symbols.json" || ! -f "$GRAPHS/AIKitMLX.symbols.json" ]]; then
    rm -rf "$SCRATCH"
    mkdir -p "$GRAPHS"
    emit_graphs
fi

# Built and run under the SAME scratch path as the graphs above, for the reason
# stated there: this script runs from inside `swift test`, and two SwiftPM
# builds sharing the package's own `.build` contend for its lock.
RENDERED="$(swift run --scratch-path "$SCRATCH" public-api-render "$GRAPHS")"

if [[ "$WRITE" == "1" ]]; then
    # Keep every `#` line already in the file: those are the review notes
    # BR-AIL-21 requires for a symbol that is public without being a door, and
    # a generator must not silently delete a justification.
    HEADER="$(grep '^#' AIKitPublicAPI.txt 2>/dev/null || true)"
    { [[ -n "$HEADER" ]] && printf '%s\n\n' "$HEADER"; printf '%s\n' "$RENDERED"; } > AIKitPublicAPI.txt
    echo "wrote AIKitPublicAPI.txt ($(printf '%s\n' "$RENDERED" | wc -l | tr -d ' ') symbols)" >&2
else
    printf '%s\n' "$RENDERED"
fi
